import type {
	McpServer,
	ReadResourceResult,
	ServerContext,
} from "@modelcontextprotocol/server";
import { Effect } from "effect";
import type { ToolRuntime } from "../tools/tool-runtime.js";
import {
	ExerciseTemplateCatalogService,
	HevyOperationsService,
} from "../effect-services.js";
import { projectRoutineFolder } from "../utils/formatters.js";
import { createExecutionErrorProjection } from "../utils/error-handler.js";
import { requireOperation } from "../tools/operation-helpers.js";
import type { RuntimeValue } from "../utils/type-predicates.js";

const JSON_MIME_TYPE = "application/json";

function createJsonResourceResult(
	uri: URL,
	data: RuntimeValue,
): ReadResourceResult {
	return {
		contents: [
			{
				uri: uri.toString(),
				mimeType: JSON_MIME_TYPE,
				text: JSON.stringify(data),
			},
		],
	};
}

function createResourceErrorResult(
	uri: URL,
	error: RuntimeValue,
): ReadResourceResult {
	return createJsonResourceResult(uri, {
		error: createExecutionErrorProjection(error),
	});
}

async function readResource(
	uri: URL,
	read: () => Effect.Effect<ReadResourceResult, unknown, never>,
): Promise<ReadResourceResult> {
	try {
		return await Effect.runPromise(Effect.suspend(read));
	} catch (error) {
		return createResourceErrorResult(uri, error);
	}
}

export function registerHevyResources(
	server: McpServer,
	runtime: ToolRuntime,
): void {
	server.registerResource(
		"user-profile",
		"hevy://user",
		{
			description: "Authenticated Hevy user profile",
			mimeType: JSON_MIME_TYPE,
		},
		async (uri, context: ServerContext) =>
			readResource(uri, () => {
				const scoped = runtime.forExecution({
					signal: context.mcpReq.signal,
				});
				return requireOperation(
					scoped.service(HevyOperationsService).user?.get,
					"user.get",
				)
					.effect(scoped.execution)
					.pipe(
						Effect.map((user) => createJsonResourceResult(uri, user ?? null)),
					);
			}),
	);

	server.registerResource(
		"workout-count",
		"hevy://workout-count",
		{
			description: "Total number of workouts in the Hevy account",
			mimeType: JSON_MIME_TYPE,
		},
		async (uri, context: ServerContext) =>
			readResource(uri, () => {
				const scoped = runtime.forExecution({
					signal: context.mcpReq.signal,
				});
				return requireOperation(
					scoped.service(HevyOperationsService).workouts.count,
					"workouts.count",
				)
					.effect(scoped.execution)
					.pipe(
						Effect.map((workoutCount) =>
							createJsonResourceResult(uri, {
								workout_count: workoutCount,
							}),
						),
					);
			}),
	);

	server.registerResource(
		"exercise-templates",
		"hevy://exercise-templates",
		{
			description: "Full formatted Hevy exercise template catalog",
			mimeType: JSON_MIME_TYPE,
		},
		async (uri, context: ServerContext) =>
			readResource(uri, () => {
				const scoped = runtime.forExecution({
					signal: context.mcpReq.signal,
				});
				return scoped
					.service(ExerciseTemplateCatalogService)
					.effect()
					.pipe(
						Effect.map((templates) => createJsonResourceResult(uri, templates)),
					);
			}),
	);

	server.registerResource(
		"routine-folders",
		"hevy://routine-folders",
		{
			description: "Full formatted list of Hevy routine folders",
			mimeType: JSON_MIME_TYPE,
		},
		async (uri, context: ServerContext) =>
			readResource(uri, () => {
				const scoped = runtime.forExecution({
					signal: context.mcpReq.signal,
				});
				return requireOperation(
					scoped.service(HevyOperationsService).folders?.listAll,
					"folders.listAll",
				)
					.effect(scoped.execution)
					.pipe(
						Effect.map((folders) =>
							createJsonResourceResult(uri, folders.map(projectRoutineFolder)),
						),
					);
			}),
	);
}

import { Effect } from "effect";
import { z } from "zod";
import type { TemplatesHistoryInput } from "@hevy-mcp/operations";
import type { ToolRuntime } from "./tool-runtime.js";
import {
	createExerciseTemplateResponse,
	exerciseHistoryResponse,
	exerciseTemplateResponse,
	searchExerciseTemplatesResponse,
} from "../utils/response-contracts.js";
import { createSafeErrorDiagnostic } from "../utils/error-policy.js";
import {
	createAnnotations,
	readOnlyAnnotations,
} from "../utils/tool-annotations.js";
import type { InferToolParams } from "../utils/tool-helpers.js";
import { exerciseTemplateInputFields, nonEmptyId } from "./input-schemas.js";
import { muscleGroupEnum } from "../utils/schemas.js";
import {
	ExerciseTemplateCatalogService,
	HevyOperationsService,
} from "../effect-services.js";
import { operationEffect, requireOperation } from "./operation-helpers.js";

const getExerciseTemplateSchema = {
	exercise_template_id: nonEmptyId,
} as const;
const isoDateTimeBase = z.iso.datetime({ offset: true });
const isoDateTimeWithOffset = z
	.string()
	.refine(
		(value) => isoDateTimeBase.safeParse(value).success,
		"Must be an ISO 8601 timestamp with an offset",
	)
	.meta({ format: "date-time" });

const getExerciseHistorySchema = {
	exercise_template_id: nonEmptyId,
	start_date: isoDateTimeWithOffset.optional(),
	end_date: isoDateTimeWithOffset.optional(),
} as const;
const createExerciseTemplateSchema = exerciseTemplateInputFields;
const searchExerciseTemplatesSchema = {
	query: z.string().min(1),
	primary_muscle_group: muscleGroupEnum.optional(),
	refresh: z.boolean().optional().default(false),
} as const;

function createHistoryInput(
	args: InferToolParams<typeof getExerciseHistorySchema>,
): TemplatesHistoryInput {
	let input = { exerciseTemplateId: args.exercise_template_id };
	if (args.start_date !== undefined) {
		input = Object.assign(input, { startDate: args.start_date });
	}
	if (args.end_date !== undefined) {
		input = Object.assign(input, { endDate: args.end_date });
	}
	return input;
}

const getExerciseTemplateDefinition = {
	name: "get-exercise-template",
	feature: "templates" as const,
	operation: "get" as const,
	description:
		"Read-only. Gets one exercise template by exercise_template_id. Use search-exercise-templates to discover IDs.",
	inputSchema: getExerciseTemplateSchema,
	outputSchema: exerciseTemplateResponse.outputSchema,
	annotations: readOnlyAnnotations("Get Exercise Template"),
	kind: "read" as const,
	responseContract: exerciseTemplateResponse,
	execute: (
		runtime: ToolRuntime,
		args: InferToolParams<typeof getExerciseTemplateSchema>,
	) =>
		operationEffect(
			requireOperation(
				runtime.service(HevyOperationsService).templates?.get,
				"templates.get",
			),
			{ exerciseTemplateId: args.exercise_template_id },
			runtime.execution,
		).pipe(
			Effect.map(
				({ exerciseTemplate, exerciseTemplateId, expected404Outcome }) => ({
					exercise_template: exerciseTemplate,
					exercise_template_id: exerciseTemplateId,
					expected404Outcome,
				}),
			),
		),
};

const getExerciseHistoryDefinition = {
	name: "get-exercise-history",
	feature: "templates" as const,
	operation: "get" as const,
	description:
		"Read-only. Returns performed sets for one exercise-template ID, optionally bounded by ISO 8601 timestamps.",
	inputSchema: getExerciseHistorySchema,
	outputSchema: exerciseHistoryResponse.outputSchema,
	annotations: readOnlyAnnotations("Get Exercise History"),
	kind: "read" as const,
	responseContract: exerciseHistoryResponse,
	execute: (
		runtime: ToolRuntime,
		args: InferToolParams<typeof getExerciseHistorySchema>,
	) => {
		const input = createHistoryInput(args);
		return operationEffect(
			requireOperation(
				runtime.service(HevyOperationsService).templates?.history,
				"templates.history",
			),
			input,
			runtime.execution,
		).pipe(
			Effect.map(({ exerciseHistory, exerciseTemplateId }) => ({
				exercise_history: exerciseHistory,
				exercise_template_id: exerciseTemplateId,
			})),
		);
	},
};

const createExerciseTemplateDefinition = {
	name: "create-exercise-template",
	feature: "templates" as const,
	operation: "create" as const,
	description:
		"Writes a custom exercise template. Search first; retries or reused titles can create duplicates.",
	inputSchema: createExerciseTemplateSchema,
	annotations: createAnnotations("Create Exercise Template"),
	kind: "write" as const,
	responseContract: createExerciseTemplateResponse,
	execute: (
		runtime: ToolRuntime,
		args: InferToolParams<typeof createExerciseTemplateSchema>,
	) =>
		operationEffect(
			requireOperation(
				runtime.service(HevyOperationsService).templates?.create,
				"templates.create",
			),
			args,
			runtime.execution,
		),
};

const searchExerciseTemplatesDefinition = {
	name: "search-exercise-templates",
	feature: "templates" as const,
	operation: "search" as const,
	description:
		"Read-only. Searches template titles case-insensitively and returns IDs. refresh reloads the five-minute catalog cache.",
	inputSchema: searchExerciseTemplatesSchema,
	outputSchema: searchExerciseTemplatesResponse.outputSchema,
	annotations: readOnlyAnnotations("Search Exercise Templates"),
	kind: "read" as const,
	responseContract: searchExerciseTemplatesResponse,
	execute: (
		runtime: ToolRuntime,
		args: InferToolParams<typeof searchExerciseTemplatesSchema>,
	) => {
		const catalog = runtime.service(ExerciseTemplateCatalogService);
		const templates = catalog.effect({
			refresh: args.refresh,
			execution: runtime.execution,
			onRefreshed: (refreshedCatalog, reason) => {
				try {
					runtime.logger?.({
						level: "info",
						logger: "hevy-cache",
						data: {
							message: "Exercise template catalog refreshed",
							count: refreshedCatalog.length,
							reason,
						},
					});
				} catch (error) {
					console.error(
						"Failed to emit structured exercise template cache log",
						createSafeErrorDiagnostic(error),
					);
				}
			},
		});

		return templates.pipe(
			Effect.map((catalogTemplates) => {
				const queryLower = args.query.toLowerCase();
				let results = catalogTemplates.filter((template) =>
					(template.title ?? "").toLowerCase().includes(queryLower),
				);
				if (args.primary_muscle_group !== undefined) {
					results = results.filter(
						(template) =>
							template.primary_muscle_group === args.primary_muscle_group,
					);
				}
				return {
					results,
					query: args.query,
					primary_muscle_group: args.primary_muscle_group,
				};
			}),
		);
	},
};

/** Ordered exercise-template tools for composition by the shared server. */
export const templateToolDefinitions = [
	getExerciseTemplateDefinition,
	getExerciseHistoryDefinition,
	createExerciseTemplateDefinition,
	searchExerciseTemplatesDefinition,
] as const;

import { preloadCompactJsonSchema } from "../utils/compact-json-schema.js";
import {
	getRegisteredToolConfig,
	registerToolDefinition,
	type ToolRegistrar,
} from "./define-tool.js";
import { bodyMeasurementToolDefinitions } from "./body-measurements.js";
import { folderToolDefinitions } from "./folders.js";
import { routineToolDefinitions } from "./routines.js";
import { templateToolDefinitions } from "./templates.js";
import { routineDiscoveryToolDefinitions } from "./routine-discovery.js";
import { workflowToolDefinitions } from "./workflows.js";
import { workoutToolDefinitions } from "./workouts.js";
import type { ToolRuntime } from "./tool-runtime.js";

export const hevyToolDefinitions = [
	...workoutToolDefinitions,
	...routineToolDefinitions,
	...templateToolDefinitions,
	...folderToolDefinitions,
	...bodyMeasurementToolDefinitions,
	...workflowToolDefinitions,
	...routineDiscoveryToolDefinitions,
] as const;

/**
 * Move the one-time tool schema conversion into module scope.
 *
 * Tool schemas are module-level constants, and their compact JSON Schema is
 * memoized per definition by `getRegisteredToolConfig`. Populating the memo is
 * not enough: `compactJsonSchema` stores the actual `z.toJSONSchema` work
 * behind lazy `input`/`output` closures, and the MCP SDK invokes those during
 * `registerTool`. This forces the exact conversions the SDK consumes (`input`
 * for each `inputSchema`, `output` for each read tool `outputSchema`) so a
 * first request only reads already-converted schemas.
 *
 * On isolate-based edge runtimes (Cloudflare Workers) module-scope work runs
 * during isolate warm-up, outside a request's billed CPU, so calling this at
 * module scope keeps the first request of a fresh isolate fast. Idempotent,
 * and a no-op after every conversion has been computed once.
 */
export function preloadHevyToolSchemas(): void {
	for (const definition of hevyToolDefinitions) {
		const config = getRegisteredToolConfig(definition);
		preloadCompactJsonSchema(config.inputSchema, "input");
		if (config.outputSchema) {
			preloadCompactJsonSchema(config.outputSchema, "output");
		}
	}
}

/** Register every Hevy tool in its production ordering. */
export function registerHevyTools(
	server: ToolRegistrar,
	runtime: ToolRuntime,
): void {
	for (const definition of hevyToolDefinitions) {
		registerToolDefinition(server, runtime, definition);
	}
}
